INSERT INTO moadbook_games.question_bank
  (question_id,category_id,category,difficulty,prompt,options,correct_index,explanation,source_title,source_url,source_evidence,enabled)
SELECT q.id, q."categoryId", q.category, q.difficulty, q.prompt,
       ARRAY(SELECT jsonb_array_elements_text(q.options)), q."correctIndex", q.explanation,
       COALESCE(NULLIF(q."sourceTitle",''),'تحقق حسابي مباشر'), q."sourceUrl", COALESCE(NULLIF(q."sourceEvidence",''),q."verificationMethod",'مراجعة حسابية داخلية'), true
FROM jsonb_to_recordset($moadbook_questions$[
{"id":"sci-01","categoryId":"science","category":"علوم","difficulty":"easy","prompt":"كم عدد الكواكب في مجموعتنا الشمسية؟","options":["سبعة كواكب","ثمانية كواكب","تسعة كواكب","عشرة كواكب"],"correctIndex":1,"explanation":"تضم المجموعة الشمسية ثمانية كواكب معترفًا بها، من عطارد إلى نبتون.","sourceTitle":"About Planets","sourceUrl":"https://science.nasa.gov/solar-system/planets/","sourceEvidence":"تذكر ناسا أن مجموعتنا الشمسية تضم ثمانية كواكب: عطارد والزهرة والأرض والمريخ والمشتري وزحل وأورانوس ونبتون."},
{"id":"sci-02","categoryId":"science","category":"علوم","difficulty":"easy","prompt":"عند أي درجة مئوية يتجمد الماء على المقياس الشائع؟","options":["0 درجة مئوية","10 درجات مئوية","50 درجة مئوية","100 درجة مئوية"],"correctIndex":0,"explanation":"على مقياس سلسيوس، يتجمد الماء عند صفر درجة مئوية تقريبًا في الظروف المعتادة.","sourceTitle":"SI Units – Temperature","sourceUrl":"https://www.nist.gov/pml/owm/si-units-temperature","sourceEvidence":"تقول صفحة المعهد الوطني للمعايير والتقنية إن الماء يتجمد عند 0 °C ويغلي عند نحو 100 °C على مقياس سلسيوس."},
{"id":"sci-03","categoryId":"science","category":"علوم","difficulty":"medium","prompt":"ما الجزيء الذي يحمل المعلومات الوراثية في الخلايا؟","options":["الحمض النووي DNA","الجلوكوز","الأكسجين","الماء"],"correctIndex":0,"explanation":"تُخزَّن المعلومات الوراثية في ترتيب النيوكليوتيدات على طول جزيء الحمض النووي DNA.","sourceTitle":"The Structure and Function of DNA - Molecular Biology of the Cell","sourceUrl":"https://www.ncbi.nlm.nih.gov/books/NBK26821/","sourceEvidence":"يوضح ملخص الفصل أن المعلومات الوراثية محمولة في التسلسل الخطي للنيوكليوتيدات في DNA."},
{"id":"sci-04","categoryId":"science","category":"علوم","difficulty":"easy","prompt":"كم تستغرق الأرض تقريبًا لتُكمل دورة واحدة حول محورها؟","options":["12 ساعة","23.9 ساعة","30 يومًا","365.25 يومًا"],"correctIndex":1,"explanation":"تُكمل الأرض دورة حول محورها في نحو 23.9 ساعة؛ أما 365.25 يومًا فهي مدة دورة الأرض حول الشمس.","sourceTitle":"Facts About Earth","sourceUrl":"https://science.nasa.gov/earth/facts/","sourceEvidence":"تذكر ناسا أن الأرض تُكمل دورة واحدة كل 23.9 ساعة أثناء دورانها حول الشمس."},
{"id":"hist-01","categoryId":"history","category":"تاريخ","difficulty":"medium","prompt":"في أي سلالة صينية استمر بناء أجزاء من سور الصين العظيم حتى أصبح أكبر منشأة عسكرية في العالم؟","options":["سلالة هان","سلالة مينغ","سلالة تانغ","سلالة تشينغ"],"correctIndex":1,"explanation":"استمر البناء حتى عهد أسرة مينغ، بين 1368 و1644م.","sourceTitle":"The Great Wall","sourceUrl":"https://whc.unesco.org/en/list/438/","sourceEvidence":"تذكر اليونسكو أن بناء السور استمر حتى عهد مينغ (1368–1644)، وأنه صار أكبر منشأة عسكرية في العالم."},
{"id":"hist-02","categoryId":"history","category":"تاريخ","difficulty":"easy","prompt":"أي حضارة قديمة شُيّد فيها الهرم الأكبر في الجيزة، المنسوب إلى الملك خوفو؟","options":["الحضارة المصرية القديمة","الحضارة الرومانية","حضارة وادي السند","الحضارة المينوية"],"correctIndex":0,"explanation":"يقع الهرم الأكبر ضمن مقبرة ممفيس المصرية، وهو من أهرامات الجيزة.","sourceTitle":"Memphis and its Necropolis – the Pyramid Fields from Giza to Dahshur","sourceUrl":"https://whc.unesco.org/en/list/86/","sourceEvidence":"تسمي اليونسكو الهرم الأكبر هرم خوفو، وتصفه بأنه العجيبة الوحيدة الباقية من عجائب العالم القديم."},
{"id":"hist-03","categoryId":"history","category":"تاريخ","difficulty":"easy","prompt":"في أي يوم اعتمد الكونغرس القاري إعلان استقلال الولايات المتحدة؟","options":["4 يوليو 1776","2 أغسطس 1776","14 يوليو 1789","1 يناير 1777"],"correctIndex":0,"explanation":"اعتمد الكونغرس الإعلان في 4 يوليو 1776؛ وبدأ المندوبون توقيعه على الرق في 2 أغسطس.","sourceTitle":"Declaration of Independence (1776)","sourceUrl":"https://www.archives.gov/milestone-documents/declaration-of-independence","sourceEvidence":"ينص الأرشيف الوطني الأمريكي على أن الكونغرس القاري اعتمد الإعلان في 4 يوليو 1776، وبدأ المندوبون توقيعه في 2 أغسطس 1776."}
]$moadbook_questions$::jsonb) AS q(
  id text, "categoryId" text, category text, difficulty text, prompt text, options jsonb,
  "correctIndex" smallint, explanation text, "sourceTitle" text, "sourceUrl" text, "sourceEvidence" text, "verificationMethod" text
)
ON CONFLICT (question_id) DO NOTHING;
